def transform(grid):
    h=len(grid); w=len(grid[0]); seen=set(); objs=[]
    for r in range(h):
        for c in range(w):
            if not grid[r][c] or (r,c) in seen: continue
            color=grid[r][c]; cells=[(r,c)]; seen.add((r,c))
            for y,x in cells:
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); cells.append((yy,xx))
            objs.append([color,cells])
    out=[row[:] for row in grid]
    changed=True
    while changed:
        changed=False
        for color,cells in sorted(objs,key=lambda a:min(x for y,x in a[1])):
            own=set(cells)
            if all(x>0 and ((y,x-1) in own or out[y][x-1]==0) for y,x in cells):
                for y,x in cells: out[y][x]=0
                cells[:]=[(y,x-1) for y,x in cells]
                for y,x in cells: out[y][x]=color
                changed=True
    return out

